/**
 * Standardized sort configuration for database queries and result ordering.
 *
 * Provides a consistent way to specify field-based sorting with directional
 * control. Used across administrative interfaces and list operations to enable
 * user-controlled result ordering while maintaining database query efficiency
 * and predictable result sets.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type ISortOption = {
  /**
   * Database field name to sort by. Common options include 'created_at',
   * 'updated_at', 'name', 'id' depending on the entity being queried.
   */
  fieldName: string;

  /** Sort direction preference for the specified field. */
  direction: "asc" | "desc";
};
